1	import { BrowserRouter, Route, Routes } from "react-router-dom";
2	import { CertHub } from "./components/CertHub";
3	import { JourneyMap } from "./components/JourneyMap";
4	import { ISO13485Map } from "./components/ISO13485Map";
5	import { DocumentWorkspace } from "./components/DocumentWorkspace";
6	import { DocumentTree } from "./components/DocumentTree";
7	import { ConceptPage } from "./components/ConceptPage";
8	import { WikiIndex } from "./components/WikiIndex";
9	
10	export default function App() {
11	  const basename = import.meta.env.BASE_URL.replace(/\/$/, "");
12	  return (
13	    <BrowserRouter basename={basename}>
14	      <Routes>
15	        {/* 인증 선택 허브 */}
16	        <Route path="/" element={<CertHub />} />
17	        {/* IVDR 여정 */}
18	        <Route path="/ivdr" element={<JourneyMap />} />
19	        <Route path="/ivdr/station/:id" element={<JourneyMap />} />
20	        {/* ISO 13485 여정 */}
21	        <Route path="/iso13485" element={<ISO13485Map />} />
22	        <Route path="/iso13485/station/:id" element={<ISO13485Map />} />
23	        {/* 공유: 문서 트리 + 작성 워크스페이스 */}
24	        <Route path="/documents" element={<DocumentTree />} />
25	        <Route path="/doc/:id" element={<DocumentWorkspace />} />
26	        {/* 공유: 개념 위키 */}
27	        <Route path="/wiki" element={<WikiIndex />} />
28	        <Route path="/wiki/:slug" element={<ConceptPage />} />
29	        <Route path="*" element={<CertHub />} />
30	      </Routes>
31	    </BrowserRouter>
32	  );
33	}
